<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const stages=computed<any[]>(()=>props.result.sobol_stages||[]),progress=computed<any>(()=>props.result.sobol_progress||null);const current=computed(()=>stages.value[stages.value.length-1]);const legacy=computed(()=>props.result.sobol||null);</script><template><div class="budget-strip"><div><small>MORRIS / 轨迹与评估</small><strong>{{result.morris.trajectory_count}} <em>× ({{result.metrics.length}} + 1)</em></strong><span>{{result.morris.evaluations}}次实际模型评估 · p={{result.morris.levels}} · Δ={{fixed(result.morris.delta,3)}}</span></div><div><small>SOBOL / 档位与基础样本</small><strong v-if="stages.length">{{stages.length}} <em>档 · 上限 n={{current.base_samples}}</em></strong><strong v-else-if="legacy">{{legacy.base_samples}} <em>基础行 · 单档</em></strong><span v-if="stages.length">最高档{{current.evaluations}}次评估 · 累计{{progress?progress.cumulative_evaluations:current.cumulative_evaluations}}次 · 扰乱2d序列</span><span v-else-if="legacy">{{legacy.evaluations}}次实际模型评估 · 扰乱2d序列</span><span v-else>尚无完成档</span></div><div><small>锁定输出 / 总体方差</small><strong>{{fixed(current?current.response_variance:legacy?legacy.response_variance:0,1)}} <em>kWh²</em></strong><span>A/B合并 · ddof=0 · seed {{result.config.seed}}</span></div></div></template>
